<?php get_header(); $layout=get_theme_mod('md_single_sidebar','right'); ?><main id="main" class="container md-magazine-layout <?php echo esc_attr($layout==='none'?'without-sidebar':'sidebar-'.$layout); ?>"><div class="md-magazine-main"><?php while(have_posts()):the_post(); ?><article <?php post_class('article-single'); ?>><a class="text-link" href="<?php echo esc_url(get_option('page_for_posts')?get_permalink(get_option('page_for_posts')):home_url('/')); ?>">← بازگشت به مجله</a><div class="eyebrow">مجله مروارید درون</div><h1><?php the_title(); ?></h1><p class="post-meta"><?php echo esc_html(get_the_date()); ?></p><?php if(has_post_thumbnail())the_post_thumbnail('large',['class'=>'single-cover']); ?><div class="entry-content"><?php the_content(); ?></div><?php wp_link_pages(); ?></article><?php comments_template(); endwhile; ?></div><?php md_magazine_sidebar($layout); ?></main><?php get_footer(); ?>